mapper.select:
SELECT id, user_id, category_id, title, content, fav, status, audit_status, origin,
       attachment_path, created_time, update_time, deleted
FROM article
WHERE user_id = #{userId}
  AND update_time > #{since}
ORDER BY update_time ASC
LIMIT #{limit}

mapper.update:
UPDATE article
SET attachment_path = #{path},
    update_time     = #{now}
WHERE id = #{id} AND user_id = #{userId}
